python3 -c "
import urllib.request, urllib.parse

# Check for more static files - other cookie images
for f in ['solved_star', 'gold_star', 'trophy', 'flag', 'win']:
  for ext in ['.png', '.gif', '.jpg']:
    url = f'http://172.17.0.1:38891/static/img/cookies/{f}{ext}'
    try:
      r = urllib.request.urlopen(url, timeout=3)
      print(f'FOUND: {url}: {r.status}')
    except: pass

# Check the CSS for xss23 differently
for path in ['/static/css/xss/xss23.css', '/static/xss23.css', '/xss23.css']:
  try:
    r = urllib.request.urlopen(f'http://172.17.0.1:38891{path}', timeout=3)
    print(f'CSS FOUND: {path}: {r.status} - {r.read()[:100]}')
  except Exception as e:
    print(f'CSS MISS: {path}: {e}')
"

